-- Deploy libroyal:lo_bibliography to pg
-- requires: lo_bibliography@research_layer
-- requires: lo_views
-- The LibreOffice bibliography view (read by libroyal.odb) as the global scope:
-- every entry of any project or document (lo_bibliography_rows('global')),
-- labels computed across all of them. The per-scope views are generated by
-- lo_sync() (lo_project_<code>, lo_document_<code>). Column contract: the 33
-- LibreOffice bibliography fields, as before; Custom3 lists the projects.

BEGIN;

DROP VIEW public.lo_bibliography;

CREATE VIEW public.lo_bibliography AS
SELECT "Identifier", "BibliographyType", "Author", "Editor", "Title", "Subtitle", "Year",
       "Publisher", "Address", "Journal", "Volume", "Number", "Pages", "ISBN", "URL",
       "Custom1", "Custom2", "Custom3", "Note", "Annote", "Booktitle", "Chapter", "Edition",
       "Howpublished", "Institution", "Month", "Organizations", "School", "Series",
       "ReportType", "Custom4", "Custom5", "LocalURL"
  FROM public.lo_bibliography_rows('global');

COMMIT;
